src = 'int sum1 = 0'
keywords = {'int'}
tokens = []
parts = src.replace('=', ' = ').split(' ')
for w in parts:
    if w == '':
        continue
    if w in keywords:
        tokens.append(('kw', w))
    elif w[0].isdigit():
        tokens.append(('num', w))
    elif w[0].isalpha():
        tokens.append(('id', w))
    else:
        tokens.append((w, w))
print(len(tokens))
print(tokens[1])
